if(form.dataset.ktaForm==='invite'){var a=D.applicants.find(x=>x.id===v.applicant_id);if(!a)throw Error('Select a valid applicant.');var email=String(v.email||'').trim().toLowerCase();if(!a.email||a.email.trim().toLowerCase()!==email)throw Error('The invitation email must exactly match the applicant email saved on the case.');var bytes=new Uint8Array(32);crypto.getRandomValues(bytes);var token=Array.from(bytes).map(x=>x.toString(16).padStart(2,'0')).join('');var digest=await crypto.subtle.digest('SHA-256',new TextEncoder().encode(token));var hash=Array.from(new Uint8Array(digest)).map(x=>x.toString(16).padStart(2,'0')).join('');var ir=await c.from('travel_agency_portal_invites').insert({business_id:b.id,applicant_id:a.id,email,token_hash:hash,expires_at:new Date(Date.now()+7*86400000).toISOString(),created_by:u});if(ir.error)throw ir.error;var link=new URL('./travel-applicant-portal.html',location.href);link.searchParams.set('invite',token);var box=document.getElementById('kta-invite-result');if(box){box.hidden=false;box.innerHTML='<b>Invitation created. Copy and send this link privately:</b><input id="ktaInviteUrl" readonly style="width:100%;padding:10px;margin-top:8px" value="'+esc(link.href)+'"><button type="button" class="kta-btn" id="ktaCopyInvite">Copy invitation link</button><p class="kta-muted">Single-use · expires in seven days · bound to '+esc(email)+'</p>'}await audit(a.id,'portal_invite_created','Applicant portal invitation created',null,email);return}
